import { detectOS, matches, isPrimaryAsset } from './compat.js?v=0.2.1';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let projects=[];let detected=detectOS(navigator.userAgent,navigator.platform,navigator.maxTouchPoints);
$('os').value=detected;
$('device').textContent='Browser detected: '+({android:'Android',windows:'Windows',macos:'macOS',linux:'Linux',ios:'iPhone / iPad'}[detected]||'Unknown OS');
if(!detected){$('os').value='linux';$('device').textContent='OS unknown — choose your setup';}
if(navigator.userAgentData?.getHighEntropyValues){navigator.userAgentData.getHighEntropyValues(['architecture','bitness']).then(x=>{if(x.bitness==='64')$('arch').value=x.architecture==='arm'?'arm64':x.architecture==='x86'?'amd64':'unknown';render();}).catch(()=>{});}
function asset(p){return p.assets.find(a=>isPrimaryAsset(p.repo,a.name)&&matches(a.name,$('os').value,$('arch').value));}
function links(p,a){const linuxInstaller=p.name==='NullClaw'&&$('os').value==='linux'&&['arm64','amd64'].includes($('arch').value)?'<a class="button" href="./install-nullclaw.sh" download>Linux installer .sh ↓</a>':'';const url=p.repo?'https://github.com/'+p.repo:null;return `<a class="button" href="./projects/${esc(p.repo.toLowerCase().replace('/','--'))}/">Install options ↗</a>`+linuxInstaller+(a?`<a class="button" href="${esc(a.url)}">Download ${esc(a.name.endsWith('.apk')?'APK':a.name.endsWith('.exe')?'EXE':'package')} ↓</a>`:'')+(url?`<a class="button secondary" href="${esc(p.releaseUrl||url+'#readme')}">${a?'Release & setup ↗':'View upstream setup ↗'}</a>`:'<span class="tag">Upstream repository not listed</span>');}
function render(){const os=$('os').value,arch=$('arch').value;const available=projects.filter(p=>asset(p)&&!p.archived);const preferred=['PicoClaw','NullClaw','ZeroClaw','OpenClaw'];available.sort((a,b)=>(preferred.indexOf(a.name)<0?99:preferred.indexOf(a.name))-(preferred.indexOf(b.name)<0?99:preferred.indexOf(b.name)));const pick=available[0];$('pick').innerHTML=pick?`<div class="pick-inner"><div><span class="eyebrow">SUGGESTED PACKAGE MATCH</span><h3>${esc(pick.name)} ↗</h3><p>${esc(pick.description)}</p><div class="asset-name">${esc(asset(pick).name)} · ${(asset(pick).size/1048576).toFixed(1)} MB · ${esc(pick.release)}</div><p>Matched by OS and architecture filename. Check release requirements before installing.</p></div><div>${links(pick,asset(pick))}</div></div>`:`<div class="pick-inner"><div><h3>${os==='ios'?'No iOS package in this catalog.':arch==='unknown'?'One more detail: your processor.':'No matching installer published.'}</h3><p>${arch==='unknown'&&os!=='ios'?'Select ARM64 or x64 to identify matching packages. Android APKs may declare their architecture in upstream documentation.':'Browse upstream setup below. Android support via a terminal is not the same as a prebuilt APK. We only show native download buttons when a matching release asset exists.'}</p></div><a class="button secondary" href="#catalog">Explore the collection ↗</a></div>`;
const query=$('search').value.toLowerCase();const filtered=projects.filter(p=>(!$('category').value||p.category===$('category').value)&&(p.name+' '+p.description+' '+p.language).toLowerCase().includes(query)&&(!$('compatible').checked||asset(p)));$('count').textContent=filtered.length+' agents';$('grid').innerHTML=filtered.map((p,i)=>{const a=asset(p);return `<article class="agent ${p===pick?'match':''}"><div class="agent-head"><div class="glyph">${['◈','⌘','◌','◇','⌁'][i%5]}</div><span class="tag">${p.archived?'ARCHIVED':a?'PACKAGE MATCH':p.category}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="meta">${esc(p.category)} · ${esc(p.language)} · ${esc(p.license)}<br>Release: ${esc(p.release||'No release verified')} · Checked ${esc(p.checked.slice(0,10))}</div><div class="actions">${links(p,a)}</div>${a?`<div class="asset-name">${esc(a.name)} · ${(a.size/1048576).toFixed(1)} MB</div>`:''}</article>`;}).join('')||'<p>No agents match these filters. Try another search or show all projects.</p>';}
for(const id of ['os','arch','compatible','search','category'])$(id).addEventListener(id==='search'?'input':'change',render);
fetch('./catalog.json?v=0.2.1').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{projects=data;$('catalog-summary').textContent=projects.filter(p=>p.repo).length+' linked projects · '+new Set(projects.map(p=>p.category)).size+' categories · official sources';render()}).catch(()=>{$('pick').textContent='Catalog could not load. Please reload to try again.'});
